import assert from 'assert'

// Import tags from cerebral - these will be transformed by babel-plugin-cerebral
import {
  state,
  props,
  sequences,
  moduleState,
  moduleSequences,
  string,
} from 'cerebral'
import * as localTags from './index'

describe('Proxy transformation', () => {
  let context
  let calls

  beforeEach(() => {
    // Track function calls for assertions
    calls = {
      getState: [],
      getSequence: [],
      getSequences: [],
    }

    // Create realistic context that mirrors how Cerebral works in production
    context = {
      module: {
        name: 'testModule',
      },
      execution: {
        name: 'testModule.someAction',
      },
      controller: {
        getState(path) {
          calls.getState.push(path)

          // Return meaningful test values based on path
          if (path === 'foo') return 'foo_value'
          if (path === 'foo.bar') return 'nested_value'
          if (path === 'items.0') return 'first_item'
          if (path === 'itemId') return 42
          if (path === 'testModule.foo') return 'module_foo_value'
          if (path === 'testModule.foo.bar') return 'module_nested_value'

          return `state_${path}`
        },
        getSequence(path) {
          calls.getSequence.push(path)

          if (path === 'doThis') return () => 'sequence_executed'
          if (path === 'foo.bar') return () => 'nested_sequence_executed'
          if (path === 'testModule.doThis')
            return () => 'module_sequence_executed'

          return null
        },
        getSequences(path) {
          calls.getSequences.push(path)
          return () => `sequences_${path}_executed`
        },
      },
      props: {
        id: 123,
        nested: {
          value: 'nestedValue',
        },
      },
    }
  })

  describe('state proxy', () => {
    it('should transform state.foo to a Tag object', () => {
      const tag = state.foo

      assert.equal(tag.type, 'state')
      assert.deepEqual(tag.strings, ['foo'])
      assert.equal(tag.getValue(context), 'foo_value')
      assert.deepEqual(calls.getState, ['foo'])
    })

    it('should transform nested state access state.foo.bar to a Tag object', () => {
      const tag = state.foo.bar

      assert.equal(tag.type, 'state')
      assert.deepEqual(tag.strings, ['foo.bar'])
      assert.equal(tag.getValue(context), 'nested_value')
      assert.deepEqual(calls.getState, ['foo.bar'])
    })

    it('should transform array index access state.items[0] to a Tag object', () => {
      const tag = state.items[0]

      assert.equal(tag.type, 'state')
      assert.ok(tag.strings[0].startsWith('items.'))
      assert.equal(tag.getValue(context), 'first_item')
      assert.deepEqual(calls.getState, ['items.0'])
    })
  })

  describe('props proxy', () => {
    it('should transform props.id to a Tag object', () => {
      const tag = props.id

      assert.equal(tag.type, 'props')
      assert.deepEqual(tag.strings, ['id'])
      assert.equal(tag.getValue(context), 123)
    })

    it('should transform props.nested.value to a Tag object', () => {
      const tag = props.nested.value

      assert.equal(tag.type, 'props')
      assert.deepEqual(tag.strings, ['nested.value'])
      assert.equal(tag.getValue(context), 'nestedValue')
    })
  })

  describe('sequences proxy', () => {
    it('should transform sequences.doThis to a Tag object', () => {
      const tag = sequences.doThis

      assert.equal(tag.type, 'sequences')
      assert.deepEqual(tag.strings, ['doThis'])

      const sequenceFn = tag.getValue(context)
      assert.equal(typeof sequenceFn, 'function')
      assert.equal(sequenceFn(), 'sequence_executed')
      assert.deepEqual(calls.getSequence, ['doThis'])
    })

    it('should transform sequences.foo.bar to a Tag object', () => {
      const tag = sequences.foo.bar

      assert.equal(tag.type, 'sequences')
      assert.deepEqual(tag.strings, ['foo.bar'])

      const sequenceFn = tag.getValue(context)
      assert.equal(typeof sequenceFn, 'function')
      assert.equal(sequenceFn(), 'nested_sequence_executed')
      assert.deepEqual(calls.getSequence, ['foo.bar'])
    })
  })

  describe('moduleState proxy', () => {
    // Test comparison between direct tag creation and proxy transformation
    it('should evaluate moduleState tag directly with root path', () => {
      // Create tag directly (non-proxy approach)
      const directTag = localTags.moduleState`foo`

      assert.equal(directTag.type, 'moduleState')
      assert.deepEqual(directTag.strings, ['foo'])

      const directResult = directTag.getValue(context)
      assert.equal(directResult, 'module_foo_value')
      assert.deepEqual(calls.getState, ['testModule.foo'])
    })

    it('should transform moduleState.foo to a Tag object', () => {
      const tag = moduleState.foo

      assert.equal(tag.type, 'moduleState')
      assert.deepEqual(tag.strings, ['foo'])

      const result = tag.getValue(context)
      assert.equal(result, 'module_foo_value')
      assert.deepEqual(calls.getState, ['testModule.foo'])
    })

    it('should transform moduleState.foo.bar to a Tag object', () => {
      const tag = moduleState.foo.bar

      assert.equal(tag.type, 'moduleState')
      assert.deepEqual(tag.strings, ['foo.bar'])

      const result = tag.getValue(context)
      assert.equal(result, 'module_nested_value')
      assert.deepEqual(calls.getState, ['testModule.foo.bar'])
    })
  })

  describe('moduleSequences proxy', () => {
    it('should transform moduleSequences.doThis to a Tag object', () => {
      const tag = moduleSequences.doThis

      assert.equal(tag.type, 'moduleSequences')
      assert.deepEqual(tag.strings, ['doThis'])

      const sequenceFn = tag.getValue(context)
      assert.equal(typeof sequenceFn, 'function')
      assert.equal(sequenceFn(), 'module_sequence_executed')
      assert.deepEqual(calls.getSequence, ['testModule.doThis'])
    })
  })

  describe('string template with proxies', () => {
    it('should transform string templates with proxies to Tag objects', () => {
      const tag = string`/items/${state.itemId}`

      assert.equal(tag.type, 'string')
      assert.equal(tag.strings[0], '/items/')
      assert.equal(tag.strings[1], '')

      // Verify the embedded state tag structure
      assert.equal(tag.values[0].type, 'state')
      assert.deepEqual(tag.values[0].strings, ['itemId'])

      const result = tag.getValue(context)
      assert.equal(result, '/items/42')
      assert.deepEqual(calls.getState, ['itemId'])
    })
  })
})
